// Interface-only languages register their translators when their module loads,
// so visitors to other languages never download those dictionaries.
const registeredTranslators = new Map();
export function registerTranslator(locale, translator) {
  registeredTranslators.set(locale, translator);
}

export function translate(value, locale = 'en') {
  if (locale === 'de') return translateGerman(value);
  const registered = registeredTranslators.get(locale);
  if (registered) return registered(value);
  if (locale !== 'zh-Hans' || typeof value !== 'string' || !value.trim()) return value;
  const text = value.trim();
  const imageText = translateImageText(value, locale);
  if (imageText !== value) return imageText;
  const pad = (translated) => value.replace(text, translated);
  if (Object.hasOwn(zh, text)) return pad(zh[text]);
  const patterns = [
    [/^Show (\d+) more models?$/, (_, n) => `再显示 ${n} 款车型`],
    [/^(\d+) models?$/, (_, n) => `${n} 款车型`],
    [/^(.+) does not state its rotor mount; confirm it before choosing rotors\.$/, (_, name) => `${name} 未说明碟片安装方式；选择碟片前请确认。`],
    [/^Your quote replaces the recorded (.+)$/, (_, price) => `你的报价取代记录的 ${price}`],
    [/^(.+?) — (Tire clearance details|Weight basis|Frame details)$/, (_, value, label) => `${translate(value, 'zh-Hans')} — ${translate(label, 'zh-Hans')}`],
    [/^(\d+) mm (front|rear)$/, (_, n, wheel) => `${n} mm ${wheel === 'front' ? '前轮' : '后轮'}`],
    [/^unknown (1×|2×)$/, (_, layout) => `${layout} 未知`],
    [/^Buying checks \((\d+)\)$/, (_, n) => `购买前核对（${n}）`],
    [/^(\d+) (?:published|complete) profiles; (\d+) partial profiles\. Missing facts remain unknown\.$/, (_, a, b) => `${a} 份完整资料；${b} 份部分资料。缺失信息保留为未知。`],
    [/^(\d+) per row$/, (_, n) => `每行 ${n} 个`],
    [/^(\d+) identical rows hidden$/, (_, n) => `已隐藏 ${n} 行相同内容`],
    [/^(\d+) wheelsets shown$/, (_, n) => `显示 ${n} 款轮组`],
    [/^(\d+) systems · reviewed (\d{4}-\d{2}-\d{2}) · latest price (\d{4}-\d{2}-\d{2})$/, (_, n, reviewed, price) => `${n} 套系统 · 复核于 ${reviewed} · 最新价格 ${price}`],
    [/^from (¥|€|US\$|£)([\d,.]+)$/, (_, symbol, amount) => `${symbol}${amount} 起`],
    [/^(from )?(€|US\$|£)([\d,.]+) official store$/, (_, from, symbol, amount) => `官方商店 ${symbol}${amount}${from ? ' 起' : ''}`],
    [/^Price observed (\d{4}-\d{2}-\d{2})\.$/, (_, date) => `报价记录于 ${date}。`],
    [/^Historical price observed (\d{4}-\d{2}-\d{2})\.$/, (_, date) => `历史报价记录于 ${date}。`],
    // Carbon-wheel reference (2026-10-20)
    [/^(\d+) wheelsets · reviewed (.+)$/, (_, n, date) => `${n} 款轮组 · 复核于 ${date}`],
    [/^(\d+(?:\/\d+)?) mm · (\d+(?:\.\d+)?) mm inner$/, (_, depth, width) => `${depth} mm · 内宽 ${width} mm`],
    [/^(\d+) kg system limit$/, (_, kg) => `系统限重 ${kg} kg`],
    [/^(\d+) kg rider limit$/, (_, kg) => `骑手限重 ${kg} kg`],
    [/^(\d+) kg limit, scope not stated$/, (_, kg) => `限重 ${kg} kg（未说明范围）`],
    [/^Center Lock · (.+) mm$/, (_, axles) => `中锁 · ${axles} mm`],
    [/^6-bolt · (.+) mm$/, (_, axles) => `六钉 · ${axles} mm`],
    [/^Rotor mount not stated · (.+) mm$/, (_, axles) => `未说明碟片安装方式 · ${axles} mm`],
    [/^Official direct store · (\d{4}-\d{2}-\d{2})$/, (_, date) => `官方直营店 · ${date}`],
    [/^Official direct store · (\d{4}-\d{2}-\d{2}) · Official direct (list|sale)$/, (_, date, kind) => `官方直营店 · ${date} · ${kind === 'list' ? '官方直营标价' : '官方直营促销价'}`],
    [/^Official direct price (.+) on (\d{4}-\d{2}-\d{2}) is not a mainland China price; enter a China quote\.( Rotor mount is not stated; confirm it before choosing rotors\.)?$/, (_, amount, date, rotor) => `官方直营价 ${amount}（${date}）不是中国大陆价格；请输入中国报价。${rotor ? zh['Rotor mount is not stated; confirm it before choosing rotors.'] : ''}`],
    // Catalog workbench (2026-10)
    [/^· (\d+) published, then (\d+) research leads$/, (_, published, leads) => `· ${published} 个已发布车型，其后 ${leads} 个研究线索`],
    [/^Show (\d+) more research leads$/, (_, n) => `再显示 ${n} 个研究线索`],
    [/^Show (\d+) results$/, (_, n) => `显示 ${n} 个结果`],
    [/^Only bikes with a seller listing for (.+)$/, (_, country) => `仅显示有卖家面向${country}上架的车型`],
    [/^frame ([^·+]+) \+ ([^·]+) plan$/, (_, frame, amount) => `车架 ${frame} + ${amount} 方案`],
    [/^frame ([^·+]+) \+ plan$/, (_, frame) => `车架 ${frame} + 方案`],
    [/^China build ([^·]*\d[^·]*)$/, (_, amount) => `中国装车 ${amount}`],
    [/^China ([^·a-z]*\d[^·]*)$/, (_, amount) => `中国 ${amount}`],
    [/^(\d+) mo old$/, (_, n) => `${n} 个月前`],
    [/^Compare the three (.+) choices$/, (_, name) => `对比三款${translate(name.charAt(0).toUpperCase() + name.slice(1), locale)}`],
    [/^(Frameset|Complete-bike) good-buy reference: below (.+)$/, (_, kind, amount) => `${kind === 'Frameset' ? '车架组' : '整车'}划算参考价：低于 ${amount}`],
    [/^(\d+(?:[.,]\d+)?) results$/, (_, n) => `${n} 个结果`],
    [/^(\d+)T chainring exceeds the frame's published (\d+)T 1× maximum\.$/, (_, teeth, limit) => `${teeth}T 牙盘超出车架公布的 ${limit}T 单盘最大值。`],
    [/^Move (.+) (left|right)$/, (_, name, direction) => `将 ${name} 向${direction === 'left' ? '左' : '右'}移动`],
    [/^Remove (.+)$/, (_, name) => `移除 ${name}`],
    [/^Category-specific facts are comparable across these (\d+) selections\.$/, (_, n) => `这些 ${n} 个选项的类别特有信息可互相比对。`],
    [/^Confirm drivetrain: tire limits are (.+)\/(.+) mm \(1×\/2×\)\. Choose a known layout before using these limits; an unknown layout has no confirmed maximum\.$/, (_, single, double) => `请确认传动：单盘／双盘限制为 ${translate(single, locale)}／${translate(double, locale)} mm。请先选择已知布局；未知布局没有已确认的最大值。`],
    [/^(.+) mm tires exceed the frame's published (.+) mm limit( for (?:1×|2×))?\.$/, (_, width, limit, layout) => `${width} mm 轮胎超出车架记录的 ${limit} mm 限制${layout ? (layout.includes('1×') ? '（单盘）' : '（双盘）') : ''}。`],
    // Build planner statuses: numbers, names and unknown counts pass through unchanged.
    [/^Brief paraphrases of substantive exact-model opinions on ride, fit, build, weight, compatibility and support\. Open each source for the full context\. Reviewed (\d{4}-\d{2}-\d{2})\.$/, (_, date) => `针对确切车型的骑行、合身、装车、重量、兼容性和售后支持等实质意见简述。完整内容请打开各条来源。复核于 ${date}。`],
    [/^Show (\d+) more opinions?$/, (_, n) => `再显示 ${n} 条意见`],
    [/^from (\d+) independent owners and reviewers$/, (_, n) => `来自 ${n} 位独立车主和评测者`],
    [/^(Positive|Mixed|Negative) (\d+)$/, (_, stance, n) => `${{ Positive: '正面', Mixed: '褒贬参半', Negative: '负面' }[stance]} ${n}`],
    [/^95% interval (\d+)–(\d+)\. Share of positive opinions, with mixed counted as half\. It summarizes sentiment for this exact model only; it is not a quality rating or comparable across models\.$/, (_, low, high) => `95% 区间 ${low}–${high}。正面意见所占比例，褒贬参半计为一半。它只汇总对该确切车型的意见倾向，不是质量评分，也不可跨车型比较。`],
    [/^(\d+) unknown$/, (_, count) => `${count} 项未知`],
    [/^(.+): (priced|included|needs one input|needs price and weight)$/, (_, name, state) => `${translate(name, locale)}：${{ priced: '已计价', included: '已包含', 'needs one input': '还需一项输入', 'needs price and weight': '需要价格和重量' }[state]}`],
    [/^(.+) known \+ (\d+) unknown$/, (_, amount, count) => `${amount} 已知 + ${count} 项未知`],
    [/^(.+) (base \/ known deltas|known) \+ (\d+) unknown$/, (_, amount, basis, count) => `${amount} ${basis === 'known' ? '已知' : '基础价／已知差额'} + ${count} 项未知`],
    [/^(Purchase total|Complete price) needs (\d+) more inputs?; (projected weight|complete weight) needs (\d+) more inputs?\.$/, (_, kind, prices, weight, weights) => `${kind === 'Purchase total' ? '购买总价' : '整车价格'}还需 ${prices} 项输入；${weight === 'projected weight' ? '预计重量' : '整车重量'}还需 ${weights} 项输入。`],
    [/^Included in (.+); not counted again\.$/, (_, name) => `已包含在 ${name} 中，不重复计算。`],
    [/^(.+) does not list (.+) frame compatibility\.$/, (_, name, standard) => `${name} 未列出与 ${standard} 车架的兼容性。`],
    [/^Rotors use (.+), but the wheelset lists (.+); confirm a compatible rotor or explicitly supported adapter\.$/, (_, rotor, hub) => `碟片使用 ${rotor}，但轮组列出的是 ${hub}；请确认兼容的碟片或明确支持的转接件。`],
    [/^(.+) requires (.+); the selected wheelset does not list it\.$/, (_, name, hub) => `${name} 需要 ${hub}；所选轮组未列出。`],
    [/^Reference kept for planning, not a purchase quote; enter the exact purchase price\. (.+) · (.+) · (.+)$/, (_, label, amount, date) => `参考价仅供规划，不是购买报价；请输入准确的购买价格。${translate(label, locale)} · ${amount} · ${date}`],
    [/^Conditional price; enter your eligible checkout quote\. (.+) · (.+) · (.+)$/, (_, condition, amount, date) => `有条件价格；请输入符合资格的实际结算报价。${translate(condition, locale)} · ${amount} · ${date}`],
    [/^(.+) bikes in China$/, (_, name) => `${name} 中国市场车型`],
    [/^(.+) publication-ready complete bikes and framesets documented for riders in China, with dated prices and model-level sources\.$/, (_, name) => `${name} 已发布的中国市场整车与车架组资料，附有日期的价格和车型级来源。`],
    [/^(.+) frameset$/, (_, name) => `${name} 车架组`],
    [/^(\d+) systems · reviewed (.+)$/, (_, count, date) => `${count} 套系统 · 复核于 ${date}`],
    [/^Select (.+) for comparison$/, (_, name) => `选择 ${name} 进行对比`],
    [/^View (.+) details$/, (_, name) => `查看 ${name} 详情`],
    [/^Filter (.+)$/, (_, name) => `筛选${translate(name[0].toUpperCase() + name.slice(1), locale)}`],
    [/^(.+) — show this brand in the catalog$/, (_, name) => `${name} — 在目录中显示该品牌`],
    [/^(\d+) matches$/, (_, n) => `${n} 个结果`],
    [/^Est\. (.+)$/, (_, price) => `估算 ${price}`],
    [/^(.+) details$/, (_, name) => `${translate(name, locale)}详情`],
    [/^(.+) · (Observed|Promo|Official|Research|Available|Historical)$/, (_, before, status) => `${before} · ${translate(status, locale)}`],
    [/^The recorded complete-bike price is (.+); the dated price record below preserves its channel and conditions\.$/, (_, price) => `记录中的整车价格为 ${price}；下方价格记录保留购买渠道、日期和适用条件。`],
    [/^The recorded complete-bike price is (.+); its date and basis remain visible below\.$/, (_, price) => `记录中的整车价格为 ${price}；日期与依据见下方。`],
    [/^The displayed (.+) estimate adds the adjustable (.+) build allowance to the latest frame price\.$/, (_, price, allowance) => `显示的 ${translate(price, locale)}，是最新车架价格加上可调的 ${allowance} 装车预算。`],
  ];
  for (const [regex, replacement] of patterns) if (regex.test(text)) return pad(text.replace(regex, replacement));
  // Only translate delimited UI values, never alter a sentence or a technical ID.
  if (text.includes(' · ')) return pad(text.split(' · ').map((s) => translate(s, locale)).join(' · '));
  return value;
}

